'AC-reporting.income-statement.1'; from decimal import Decimal; from src.reporting.extension.income_statement import _fold_and_deduplicate_lines
def test_fold_and_deduplicate_income_lines(): raw_lines = [{'name': 'Income - Other', 'type': 'income', 'amount': Decimal('0.00'), 'source_currency': 'SGD'}, {'name': 'Income - Other', 'type': 'income', 'amount': Decimal('150.00'), 'source_currency': 'SGD'}, {'name': 'Income - Other', 'type': 'income', 'amount': Decimal('0.00'), 'source_currency': 'SGD'}, {'name': 'Income - Salary', 'type': 'income', 'amount': Decimal('5000.00'), 'source_currency': 'SGD'}, {'name': 'Expense - Other', 'type': 'expense', 'amount': Decimal('0.00'), 'source_currency': 'SGD'}]; folded = _fold_and_deduplicate_lines(raw_lines, filter_zero=True); assert len(folded) == 2; assert folded[0]['name'] == 'Income - Other'; assert folded[0]['amount'] == Decimal('150.00'); assert folded[1]['name'] == 'Income - Salary'; assert folded[1]['amount'] == Decimal('5000.00'); _m1_raw_lines = [{'name': 'Income - Other', 'type': 'income', 'amount': Decimal('0.00'), 'source_currency': 'SGD'}, {'name': 'Income - Other', 'type': 'income', 'amount': Decimal('0.00'), 'source_currency': 'SGD'}]; _m1_folded = _fold_and_deduplicate_lines(_m1_raw_lines, filter_zero=False); assert len(_m1_folded) == 1; assert _m1_folded[0]['name'] == 'Income - Other'; assert _m1_folded[0]['amount'] == Decimal('0.00'); _m2_raw_lines = [{'name': 'Fee Account', 'type': 'expense', 'amount': Decimal('10.00'), 'source_currency': 'SGD', 'economic_report_line_id': 'econ-fee-1'}, {'name': 'Fee Account', 'type': 'expense', 'amount': Decimal('20.00'), 'source_currency': 'SGD', 'economic_report_line_id': 'econ-fee-2'}, {'name': 'Fee Account', 'type': 'expense', 'amount': Decimal('5.00'), 'source_currency': 'SGD', 'economic_report_line_id': 'econ-fee-1'}]; _m2_folded = _fold_and_deduplicate_lines(_m2_raw_lines, filter_zero=True); assert len(_m2_folded) == 2; _m2_econ_1 = next((_m2_x for _m2_x in _m2_folded if _m2_x['economic_report_line_id'] == 'econ-fee-1')); _m2_econ_2 = next((_m2_x for _m2_x in _m2_folded if _m2_x['economic_report_line_id'] == 'econ-fee-2')); assert _m2_econ_1['amount'] == Decimal('15.00'); assert _m2_econ_2['amount'] == Decimal('20.00')
